1	#!/usr/bin/env node
2	// stage0-ladder-autofire.cjs (v2 — direct execution)
3	//
4	// UserPromptSubmit hook that AUTO-EXECUTES the non-Google Research Source Ladder
5	// when user invokes a research-trigger command. The hook itself runs the Python
6	// ladder runner, parses JSON output, and injects structured findings into Claude's
7	// context BEFORE Claude sees the prompt.
8	//
9	// Key change from v1: hook does the work, doesn't just remind. By the time Claude
10	// reads the user prompt, the ladder has already probed 15-30 sources and the
11	// drill-recommended list is in context.
12	//
13	// Triggers: /stage0, /ck:brainstorm, /ck:opportunity, /brainstorm, /venture,
14	//           /launch, /startup. EXCLUDED: /ck:test, /ck:validate (per user request —
15	//           these are hypothesis tests, not exhaustive research).
16	//
17	// Performance:
18	// - Cache hit (within route TTL) → ~50ms
19	// - Cache miss → 15-25s (parallel ladder execution)
20	// - Topic <10 chars → skipped (not a real research request)
21	//
22	// Ships as part of ugblackmmo-content-extraction-gap fix v2 (2026-04-11).
23	
24	const fs = require('fs');
25	const path = require('path');
26	const { spawnSync } = require('child_process');
27	
28	const VENV_PYTHON = 'D:/code/invesments/master_investments/.claude/skills/.venv/Scripts/python.exe';
29	const RUNNER_PATH = 'D:/code/invesments/master_investments/data/knowledge-sources/ladder-runner.py';
30	const LADDER_JSON_PATH = 'D:/code/invesments/master_investments/data/knowledge-sources/research-ladder.json';
31	const RUNNER_TIMEOUT_MS = 60000; // 60s — covers multi-route + drill mode
32	const MIN_TOPIC_LENGTH = 10;
33	const ENABLE_DRILL = true; // deep-fetch top sources after probe for richer signals
34	
35	let payload = {};
36	try {
37	  const raw = fs.readFileSync(0, 'utf-8');
38	  if (raw && raw.trim()) payload = JSON.parse(raw);
39	} catch (_e) {
40	  process.exit(0);
41	}
42	
43	const prompt = (payload.prompt || payload.user_prompt || payload.message || '').toString();
44	if (!prompt) process.exit(0);
45	
46	// Trigger patterns (excluded /ck:test, /ck:validate per user request)
47	const TRIGGERS = [
48	  /\/stage0\b/i,
49	  /\/ck:brainstorm\b/i,
50	  /\/ck:opportunity\b/i,
51	  /\/brainstorm\b/i,
52	  /\/venture\b/i,
53	  /\/launch\b/i,
54	  /\/startup\b/i,
55	];
56	const triggered = TRIGGERS.some((r) => r.test(prompt));
57	if (!triggered) process.exit(0);
58	
59	// Route classifier — weighted keyword scoring across 13 routes
60	const ROUTE_KEYWORDS = {
61	  vn_greyhat_mmo: [
62	    'black mmo', 'vn mmo', 'kiếm tiền online', 'mmo việt', 'mmo vietnam', 'in-app',
63	    'checkout fraud', 'đội nhóm', 'telegram vn', 'cash out', 'bin cc', 'nguyên liệu',
64	    'cuốc xẻng', 'ugblackmmo', 'ugvietnam', 'mmo4me', 'blackmmo', 'black hat vn',
65	    'vịt', 'affiliate vn', 'cpa vn', 'voz.vn', 'vn-z',
66	  ],
67	  vn_legitimate_business: [
68	    'vietnam business', 'vn smb', 'kinh doanh vn', 'doanh nghiệp việt', 'thương mại điện tử việt',
69	    'shopee vn', 'lazada vn', 'tiki', 'momo', 'zalopay', 'vnpay',
70	  ],
71	  western_bootstrap_saas: [
72	    'bootstrap', 'bootstrapped', 'micro-saas', 'micro saas', 'indie hacker', 'indiehacker',
73	    'solo founder', 'solo saas', 'mrr', 'indie maker', 'build in public',
74	    'one-person business', 'microconf', 'starter story',
75	  ],
76	  technical_deep_research: [
77	    'library deep', 'code architecture', 'framework internal', 'how does x work',
78	    'implementation pattern', 'api design', 'protocol spec',
79	    'data structure', 'algorithm', 'open source code',
80	  ],
81	  market_regulatory: [
82	    'is it legal', 'compliance', 'regulatory', 'license required', 'court record',
83	    'masothue', 'entity verification', 'tax registry', 'company filing', 'sec filing',
84	    'gdpr', 'hipaa', 'soc2', 'kyc', 'aml',
85	  ],
86	  supply_chain_sourcing: [
87	    'sourcing', 'factory', 'alibaba', 'import export', 'trade data', 'hs code',
88	    'panjiva', 'container', 'moq', 'supplier', 'logistics', 'freight',
89	  ],
90	  competitor_intelligence: [
91	    'competitor teardown', 'product teardown', 'stack analysis', 'builtwith',
92	    'competitor research', 'reverse engineer business', 'competitive intel',
93	  ],
94	  creator_economy: [
95	    'tiktok creator', 'youtube creator', 'influencer', 'cpm rpm', 'sponsor rate',
96	    'creator fund', 'channel analysis', 'content creator', 'subscribers',
97	    'live stream', 'short form', 'reels', 'photo slideshow',
98	  ],
99	  content_creator_western: [
100	    'youtube monetization', 'twitch', 'patreon', 'substack', 'newsletter monetization',
101	    'podcast monetization', 'beehiiv',
102	  ],
103	  crypto_grey: [
104	    'web3', 'onchain', 'on-chain', 'defi', 'airdrop', 'nft', 'smart contract',
105	    'ethereum', 'solana', 'crypto', 'erc-20', 'token launch', 'farcaster',
106	  ],
107	  ai_tools_grey: [
108	    'gpt wrapper', 'ai saas', 'ai automation', 'llm wrapper', 'claude api',
109	    'openai api', 'ai agent', 'ai workflow', 'midjourney', 'stable diffusion',
110	  ],
111	  asia_outbound: [
112	    'china outbound', 'cn ecommerce', 'shopify japan', 'kr ecommerce', 'asia export',
113	    'taobao', 'pinduoduo', 'rakuten', 'coupang',
114	  ],
115	  founder_due_diligence: [
116	    'due diligence', 'founder background', 'verify founder', 'real identity',
117	    'masothue search', 'phá sản', 'serial entrepreneur',
118	  ],
119	};
120	
121	const promptLower = prompt.toLowerCase();
122	const matchedRoutes = [];
123	for (const [route, keywords] of Object.entries(ROUTE_KEYWORDS)) {
124	  const hits = keywords.filter((kw) => promptLower.includes(kw));
125	  if (hits.length > 0) {
126	    matchedRoutes.push({ route, hits: hits.slice(0, 3), score: hits.length });
127	  }
128	}
129	matchedRoutes.sort((a, b) => b.score - a.score);
130	const topRoutes = matchedRoutes.slice(0, 2); // fire top 2 routes for ambiguous topics
131	
132	// Extract topic
133	let topic = prompt.replace(/^.*?\/(stage0|ck:\w+|brainstorm|venture|launch|startup)\b\s*/i, '').trim();
134	if (topic.length > 280) topic = topic.substring(0, 280);
135	
136	// Skip if topic is too short to be a real research request
137	if (topic.length < MIN_TOPIC_LENGTH) {
138	  process.exit(0);
139	}
140	
141	// Run the ladder for each detected route, collect results
142	function runLadder(topic, route) {
143	  if (!fs.existsSync(VENV_PYTHON) || !fs.existsSync(RUNNER_PATH)) {
144	    return { error: 'runner_not_found', _route: route };
145	  }
146	  const args = [RUNNER_PATH, '--topic', topic, '--route', route, '--json'];
147	  if (ENABLE_DRILL) args.push('--drill');
148	  const result = spawnSync(
149	    VENV_PYTHON,
150	    args,
151	    {
152	      timeout: RUNNER_TIMEOUT_MS,
153	      env: { ...process.env, PYTHONIOENCODING: 'utf-8' },
154	      maxBuffer: 32 * 1024 * 1024, // 32 MB (drill mode produces larger output)
155	    }
156	  );
157	  if (result.status !== 0) {
158	    return {
159	      error: 'runner_failed',
160	      _route: route,
161	      stderr: (result.stderr || '').toString().slice(-800),
162	      status: result.status,
163	    };
164	  }
165	  try {
166	    return JSON.parse(result.stdout.toString());
167	  } catch (e) {
168	    return { error: 'json_parse_failed', _route: route, raw: result.stdout.toString().slice(0, 500) };
169	  }
170	}
171	
172	// If no route detected, emit guidance only (don't fail entirely)
173	const lines = [];
174	lines.push('## 🔬 Non-Google Research Source Ladder — AUTO-EXECUTED');
175	lines.push('');
176	
177	if (topRoutes.length === 0) {
178	  lines.push('⚠ No route auto-detected from prompt keywords. Claude MUST manually classify topic into one of:');
179	  lines.push('`vn_greyhat_mmo`, `vn_legitimate_business`, `western_bootstrap_saas`, `technical_deep_research`, `market_regulatory`, `supply_chain_sourcing`, `competitor_intelligence`, `creator_economy`, `content_creator_western`, `crypto_grey`, `ai_tools_grey`, `asia_outbound`, `founder_due_diligence`');
180	  lines.push('');
181	  lines.push('Then run:');
182	  lines.push('```bash');
183	  lines.push(`${VENV_PYTHON} ${RUNNER_PATH} --topic "${topic.replace(/"/g, '\\"')}" --route <route_key> --json`);
184	  lines.push('```');
185	  const out = { hookSpecificOutput: { hookEventName: 'UserPromptSubmit', additionalContext: lines.join('\n') } };
186	  process.stdout.write(JSON.stringify(out));
187	  process.exit(0);
188	}
189	
190	// Fire ladder for top route(s)
191	const allResults = [];
192	for (const { route } of topRoutes) {
193	  const result = runLadder(topic, route);
194	  allResults.push({ route, result });
195	}
196	
197	// Format injection
198	lines.push(`**Topic:** ${topic}`);
199	lines.push(`**Routes auto-detected:** ${topRoutes.map((r) => `\`${r.route}\` (${r.score} kw hits: ${r.hits.join(', ')})`).join(' + ')}`);
200	lines.push('');
201	
202	let totalDrill = 0;
203	let totalSkipped = 0;
204	let totalErrored = 0;
205	let anyRunnerWorked = false;
206	
207	for (const { route, result } of allResults) {
208	  lines.push(`### Route: \`${route}\``);
209	  if (result.error) {
210	    lines.push(`❌ Runner error: ${result.error}`);
211	    if (result.stderr) lines.push('```');
212	    if (result.stderr) lines.push(result.stderr);
213	    if (result.stderr) lines.push('```');
214	    lines.push('');
215	    continue;
216	  }
217	  anyRunnerWorked = true;
218	  const summary = result.summary || {};
219	  const cacheHit = result._cache_status === 'hit';
220	  lines.push(`**Cache:** ${cacheHit ? 'HIT (instant)' : `MISS (${result.elapsed_sec || '?'}s)`}`);
221	  lines.push(`**Tiers probed:** ${(result.tiers_probed || []).join(', ')}`);
222	  lines.push(`**Total sources:** ${result.total_sources || 0}`);
223	  lines.push(`**Drill recommended:** ${summary.drill_recommended_count || 0}`);
224	  lines.push(`**Skipped (low signal):** ${summary.skipped_count || 0}`);
225	  lines.push(`**Errored:** ${summary.errored_count || 0}`);
226	  lines.push(`**Tool refs (skipped clean):** ${summary.tool_skipped_count || 0}`);
227	  lines.push('');
228	  totalDrill += summary.drill_recommended_count || 0;
229	  totalSkipped += summary.skipped_count || 0;
230	  totalErrored += summary.errored_count || 0;
231	
232	  const drillSrcs = summary.drill_recommended_sources || [];
233	  if (drillSrcs.length > 0) {
234	    lines.push(`**🎯 Deep-drill these sources NOW** (signal density confirmed):`);
235	    for (const src of drillSrcs) {
236	      const name = src.name || src;
237	      const url = src.url || '';
238	      const sig = src.signals || '';
239	      const examples = (src.examples || []).slice(0, 3).join(' | ');
240	      lines.push(`- **${name}** [${sig} signals] ${url}`);
241	      if (examples) lines.push(`  - Examples: ${examples}`);
242	    }
243	    lines.push('');
244	  }
245	
246	  if ((summary.errored_sources || []).length > 0) {
247	    lines.push(`**⚠ Errored sources** (consider Playwright escalation if signal is critical):`);
248	    for (const e of summary.errored_sources.slice(0, 8)) {
249	      lines.push(`- ${e}`);
250	    }
251	    lines.push('');
252	  }
253	}
254	
255	if (anyRunnerWorked) {
256	  // Inject deep drill snippets if drill mode succeeded
257	  for (const { route, result } of allResults) {
258	    const drillResults = (result && result.drill_results) || [];
259	    if (drillResults.length > 0) {
260	      lines.push('---');
261	      lines.push(`### 🔍 Deep-drill snippets (route \`${route}\`)`);
262	      lines.push('');
263	      for (const dr of drillResults.slice(0, 8)) {
264	        lines.push(`**${dr.source}** — ${dr.deep_signal_count || 0} deep signals from ${dr.url}`);
265	        if (dr.deep_signals && dr.deep_signals.length > 0) {
266	          lines.push('Top signals:');
267	          for (const sig of dr.deep_signals.slice(0, 12)) {
268	            lines.push(`  - ${sig}`);
269	          }
270	        }
271	        if (dr.snippet) {
272	          const cleaned = dr.snippet.replace(/\s+/g, ' ').substring(0, 400);
273	          lines.push(`Snippet: ${cleaned}...`);
274	        }
275	        lines.push('');
276	      }
277	    }
278	  }
279	
280	  // Auto-spawn instructions for Claude — explicit, copy-paste-ready Task spawn block
281	  lines.push('---');
282	  lines.push(`## 🤖 MANDATORY auto-spawn block — execute IMMEDIATELY in next response`);
283	  lines.push('');
284	  lines.push(`Per [EXHAUSTIVE-RESEARCH] rule, you MUST spawn ${Math.min(totalDrill, 8)} parallel Task agents`);
285	  lines.push(`in your VERY NEXT message to deep-extract from the drill-recommended sources above.`);
286	  lines.push(`Use a single message with multiple Agent tool calls (parallel execution).`);
287	  lines.push('');
288	  lines.push(`Each Task agent prompt template:`);
289	  lines.push('```');
290	  lines.push(`Task: Deep-extract operator-layer signals for topic "<TOPIC>" from <SOURCE_URL>.`);
291	  lines.push(``);
292	  lines.push(`Goal: extract ALL specific data points: dollar amounts (with context),`);
293	  lines.push(`dated events (with year), named entities (real people/companies), tool/product names`);
294	  lines.push(`(with vendor), URLs, ban/platform mentions, failure/scam examples.`);
295	  lines.push(``);
296	  lines.push(`For forum sources (mmo4me, voz, vn-z, V2EX, 52pojie): walk top 5-10 threads matching topic.`);
297	  lines.push(`For news sources (vnexpress, tuoitre, dantri, congan): walk top 10 articles.`);
298	  lines.push(`For dashboard sources (IndieHackers, Plausible, MicroConf): extract dated MRR + revenue numbers.`);
299	  lines.push(``);
300	  lines.push(`Use WebFetch for retrieval. If 403/422/429, escalate to method_chain_fetcher.`);
301	  lines.push(`Return structured findings with source URL citations. Under 600 words.`);
302	  lines.push('```');
303	  lines.push('');
304	  lines.push(`Substitute \`<TOPIC>\` and \`<SOURCE_URL>\` for each drill-recommended source listed above.`);
305	  lines.push('');
306	  lines.push(`## 📋 Action plan (BLOCKING per [EXHAUSTIVE-RESEARCH]):`);
307	  lines.push(`1. **Spawn ${Math.min(totalDrill, 8)} Task agents in parallel** in your next response (single message, multiple Agent tool calls)`);
308	  lines.push(`2. **Wait for results** — each agent returns structured findings with citations`);
309	  lines.push(`3. **Synthesize** findings into the verdict, with mandatory \`## Research tiers fired\` section`);
310	  lines.push(`4. **Do NOT use WebSearch as primary** — that violates the rule. WebSearch is only for URL discovery.`);
311	  lines.push(`5. **Cite drill snippets** above — they contain raw signal you can quote directly`);
312	  lines.push('');
313	  lines.push(`**Reference:** \`${LADDER_JSON_PATH}\` | \`${RUNNER_PATH}\` | \`.claude/rules/learned-rules.md\` → "Exhaustive Research Rules"`);
314	}
315	
316	const out = {
317	  hookSpecificOutput: {
318	    hookEventName: 'UserPromptSubmit',
319	    additionalContext: lines.join('\n'),
320	  },
321	};
322	process.stdout.write(JSON.stringify(out));
323	process.exit(0);
324
